//
// The AudioWorkletProcessor: a ring of `windowLength` samples, one copy of the
// newest window posted every `hopSamples` frames, and the per-hop peak.
//
// THIS FILE HAS NO IMPORTS, ON PURPOSE. An AudioWorklet global scope is not a
// document and, in more than one engine, not a module graph either: whatever
// `addModule()` fetches is what runs. The types below are therefore DECLARED
// rather than imported (`@types/audioworklet` would be a new devDependency,
// which W1 does not take — ADR 0021 decision 4's allowlist discipline), and the
// ring arithmetic is written out rather than shared with `dsp/`. Duplication is
// a real cost and it is paid deliberately: what is duplicated here is index
// bookkeeping, not a convention — nothing in this file decides a window, a
// normalisation or a dB reference, so nothing in this file can drift away from
// ADR 0006.
//
// WHAT RUNS ON THE AUDIO THREAD, AND WHAT DOES NOT. `process()` is called every
// 128 frames on a real-time thread; a missed deadline is an audible glitch and,
// here, a hole in the spectrogram. So this file does three things and no
// others: copy into a preallocated ring, track `|x|` for the hop, and
// `postMessage` a window when one is due. It also ACCEPTS one message — a
// stream change, which empties the ring; see the constructor for why a file
// seek needs it and why the frame counter survives it. No FFT (that is the Worker), no
// allocation in the steady state except the one `Float32Array` per hop that is
// TRANSFERRED away, no dB, no smoothing. It is `peak.py`'s `SampleRing` rule —
// "no allocation, no I/O, no locks, no per-sample Python" — in the one place
// this application has a genuinely real-time thread.
//
// WHY THE HOP COPY IS ALLOCATED AND TRANSFERRED, not reused. A transferred
// ArrayBuffer is DETACHED here the moment it is posted, so a reused buffer
// would be unusable on the next hop; the alternative (a pool returned by the
// main thread) makes the audio thread wait on a message it may not have
// received yet. One allocation per hop — 50 per second at the live presets —
// is the cheaper of the two, and it is the only allocation in the loop.
//
// WHY `peakAbs` IS COMPUTED HERE. The clip latch has to see the RAW capture:
// after the window, the DC blocker and the transform, a sample at ±1.0 is a
// number nobody can recover. This is the last stage that sees the samples as
// the device delivered them, so this is where the peak magnitude is measured.
// The THRESHOLD is not applied here — `worker/protocol.ts` owns that constant,
// so there is one place to change it — and `peakAbs` is posted as a number.
// ----------------------------------------------------------------------------

/* --- the AudioWorklet global scope, declared rather than imported ---------- */
/* `moduleDetection: "force"` makes this file a module, so these declarations
   are module-scoped and cannot leak into the rest of the application. */

/** The context's sample rate, a global of the AudioWorklet scope. */
declare const sampleRate: number;

/** The context's clock, in seconds, at the start of the current render quantum. */
declare const currentTime: number;

/** Registers a processor class under the name `addModule`'s caller will construct. */
declare function registerProcessor(name: string, processorCtor: unknown): void;

interface AudioWorkletProcessorLike {
  readonly port: MessagePort;
}

declare const AudioWorkletProcessor: {
  prototype: AudioWorkletProcessorLike;
  new (options?: unknown): AudioWorkletProcessorLike;
};

/** What `session.ts` passes through `AudioWorkletNodeOptions.processorOptions`. */
interface PcmHopOptions {
  readonly windowLength?: number;
  readonly hopSamples?: number;
}

/** The name `capture.ts` constructs. Changing it changes both files or neither. */
const PROCESSOR_NAME = 'spectral-pcm-hop';

class PcmHopProcessor extends AudioWorkletProcessor {
  /** `windowLength` samples of history — exactly one analysis window, never more. */
  private readonly ring: Float32Array;
  private readonly windowLength: number;
  private readonly hopSamples: number;

  /** Where the next sample goes; the ring is full from `write` backwards once `filled` reaches its length. */
  private write = 0;
  private filled = 0;
  private sinceHop = 0;

  /** Monotonic hop counter — the Worker's and the view's frame identity. */
  private frameIndex = 0;

  /** max |x| since the last posted hop, on the RAW capture. */
  private hopPeak = 0;

  /** Every input sample this processor has consumed. The main thread's gap detector. */
  private consumed = 0;

  constructor(options?: { readonly processorOptions?: PcmHopOptions }) {
    super(options);
    const requestedWindow = options?.processorOptions?.windowLength;
    const requestedHop = options?.processorOptions?.hopSamples;
    if (!Number.isInteger(requestedWindow) || (requestedWindow as number) < 2) {
      throw new RangeError(
        `${PROCESSOR_NAME}: processorOptions.windowLength must be an integer >= 2 (the preset's fft_size), got ${String(requestedWindow)}`,
      );
    }
    if (!Number.isInteger(requestedHop) || (requestedHop as number) < 1) {
      throw new RangeError(
        `${PROCESSOR_NAME}: processorOptions.hopSamples must be a positive integer (the preset's resolution.hop_samples), got ${String(requestedHop)}`,
      );
    }
    this.windowLength = requestedWindow as number;
    this.hopSamples = requestedHop as number;
    this.ring = new Float32Array(this.windowLength);

    // THE ONE MESSAGE THIS PROCESSOR ACCEPTS: a stream change.
    //
    // The ring holds the last `windowLength` samples of a CONTINUOUS stream.
    // When the file source seeks, changes its loop region or restarts, the
    // samples in it are from a position the audio is no longer at, and the
    // next window posted would be up to `windowLength − hopSamples` of before
    // the jump glued to the samples after it — a spectrum of a signal that
    // never existed, drawn into the spectrogram as if it had. Zeroing `filled`
    // makes the processor wait for a genuinely full window instead (the
    // `filled < windowLength` rule below), which costs one window of frames —
    // 128 ms at live_singing — and buys a record with no invented column in it.
    //
    // `frameIndex` and `consumed` are NOT reset: they are identity and a gap
    // detector, and a counter that restarted would make two different columns
    // claim the same index.
    this.port.onmessage = (event: MessageEvent): void => {
      if ((event.data as { type?: string } | null)?.type === 'reset') {
        this.write = 0;
        this.filled = 0;
        this.sinceHop = 0;
        this.hopPeak = 0;
      }
    };
  }

  /**
   * One render quantum. Returns `true` for as long as this node should live.
   *
   * `true`, not `false`, even with no input connected: the node is built with
   * zero outputs and is kept alive by its input edge, and returning `false`
   * once would end the processor permanently — a capture that silently stops
   * the first time the graph is momentarily empty.
   */
  process(inputs: Float32Array[][]): boolean {
    // Channel 0 only. A multichannel device is down-mixed by the graph before
    // it reaches here (the node is built `channelCount: 1`, explicit), and
    // summing channels ourselves would change the level by a convention
    // nobody wrote down — `io/wav.ts` refuses a multichannel file for the
    // same reason.
    const channel = inputs[0]?.[0];
    if (channel === undefined || channel.length === 0) {
      return true;
    }

    const { ring, windowLength, hopSamples } = this;
    let { write, filled, sinceHop, hopPeak } = this;

    for (let i = 0; i < channel.length; i += 1) {
      // Counted BEFORE the hop test, so that a window posted inside this loop
      // stamps `sampleCount` with the sample it actually ends on rather than
      // with the count at the start of the quantum.
      this.consumed += 1;
      const x = channel[i] as number;
      const magnitude = x < 0 ? -x : x;
      if (magnitude > hopPeak) {
        hopPeak = magnitude;
      }
      ring[write] = x;
      write = write + 1 === windowLength ? 0 : write + 1;
      if (filled < windowLength) {
        filled += 1;
      }
      sinceHop += 1;

      // A hop is due. `while` rather than `if` so that a hop shorter than a
      // render quantum (128 frames) still posts once per hop instead of
      // silently dropping to one post per quantum — no preset asks for that
      // today (the shortest hop is 320) and a future one must not fail quietly.
      while (sinceHop >= hopSamples) {
        sinceHop -= hopSamples;
        if (filled < windowLength) {
          // Still filling the first window: the hop counter advances (so the
          // grid stays on the preset's hop) but there is no full window to
          // describe yet, and a zero-padded one would be a spectrum of
          // silence that never existed.
          continue;
        }
        this.postWindow(write, hopPeak);
        hopPeak = 0;
      }
    }

    this.write = write;
    this.filled = filled;
    this.sinceHop = sinceHop;
    this.hopPeak = hopPeak;
    return true;
  }

  /**
   * Copy the newest window out of the ring, oldest sample first, and post it.
   *
   * `end` is the ring index one past the newest sample, so the window starts
   * at the same index — the ring holds exactly one window, and `set` of two
   * slices is the unwrap.
   */
  private postWindow(end: number, peakAbs: number): void {
    const { ring, windowLength } = this;
    const samples = new Float32Array(windowLength);
    const tail = windowLength - end;
    samples.set(ring.subarray(end), 0);
    samples.set(ring.subarray(0, end), tail);
    this.port.postMessage(
      {
        samples,
        frameIndex: this.frameIndex,
        // The AudioContext clock, in ms. NOT `performance.now()` and NOT the
        // Worker's clock: those are different time origins, and this one is
        // the only clock whose ticks are the samples. It is a frame STAMP, not
        // a latency: ADR 0021 decision 3 says the web application's latency is
        // measured on a rig (experiment 0007), never subtracted out of two
        // clocks that were never zeroed against each other.
        capturedAtMs: currentTime * 1000,
        // Every input sample consumed since this processor started, including
        // the ones in the quantum being processed up to this hop. The main
        // thread can difference it across hops to see a gap; nothing in W1
        // does, and a field nobody can check is a field that lies later.
        sampleCount: this.consumed,
        peakAbs,
        // Stated per hop rather than assumed by the reader: the Worker
        // asserts it against the preset's `sample_rate_hz`, which is the
        // second half of ADR 0021 decision 7(c)'s assertion.
        sampleRateHz: sampleRate,
      },
      [samples.buffer],
    );
    this.frameIndex += 1;
  }
}

registerProcessor(PROCESSOR_NAME, PcmHopProcessor);
